import React, { useState, useEffect } from 'react';
import faqData from './data/faqData.json';
import Category from './components/Category';
import './styles.css';

function App() {
  const [categories, setCategories] = useState([]);

  useEffect(() => {
    const savedVotes = JSON.parse(localStorage.getItem('faqVotes')) || {};
    const updatedData = faqData.map(cat => ({
      ...cat,
      questions: cat.questions.map(q => ({
        ...q,
        rating: savedVotes[q.id] ?? q.rating
      }))
    }));
    setCategories(updatedData);
  }, []);

  const updateRating = (catName, qId, delta) => {
    setCategories(prev =>
      prev.map(cat =>
        cat.category === catName
          ? {
              ...cat,
              questions: cat.questions.map(q =>
                q.id === qId ? { ...q, rating: q.rating + delta } : q
              )
            }
          : cat
      )
    );
  };

  useEffect(() => {
    const votes = {};
    categories.forEach(cat => {
      cat.questions.forEach(q => {
        votes[q.id] = q.rating;
      });
    });
    localStorage.setItem('faqVotes', JSON.stringify(votes));
  }, [categories]);

  const sortedCategories = [...categories].sort((a, b) => {
    const sumA = a.questions.reduce((sum, q) => sum + q.rating, 0);
    const sumB = b.questions.reduce((sum, q) => sum + q.rating, 0);
    return sumB - sumA;
  });

  return (
    <div className="container">
      <h1>Часто задаваемые вопросы</h1>
      {sortedCategories.map(cat => (
        <Category
          key={cat.category}
          category={cat}
          onVote={updateRating}
        />
      ))}
    </div>
  );
}

export default App;
